UPDATE sys_lock_info
SET JSH = #{classroomNumber}, switch_status=NULL, observed_at=NULL, remarks = #{remarks}, classroom_id=#{classroomId}, door_channel=#{doorChannel}
WHERE lock_id = #{lockId}

UPDATE sys_lock_info
SET switch_status = #{switchStatus}, observed_at=CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')
WHERE lock_id = #{lockId}
